import type {
    TrackerSelectGroup,
    TrackerSelectItemValueBase,
    TrackerSelectItems,
} from '../../../components/TrackerSelect/types';

/**
 * Filters items within each group by matching search string against item.id and item.display.
 * Groups with no matching items are still returned (with empty items).
 */
export function filterGroups<Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase>(
    groups: TrackerSelectGroup<Value>[] | undefined,
    search: string,
): TrackerSelectGroup<Value>[] | undefined {
    if (!groups) {
        return undefined;
    }

    const filterSearch = search.toLowerCase();

    if (!filterSearch) {
        return groups;
    }

    return groups.map((group) => {
        const items: TrackerSelectItems<Value> = {};

        for (const [key, value] of Object.entries(group.items ?? {})) {
            const item = value as TrackerSelectGroup<Value>['items'][string];
            const {id, display} = item;

            if (
                id.toLowerCase().includes(filterSearch) ||
                display.toLowerCase().includes(filterSearch)
            ) {
                items[key] = item;
            }
        }

        return {
            ...group,
            items,
        };
    });
}
